export const MAX_LOCKED_ACCOUNTS = 64;

type Cluster = 'devnet' | 'testnet' | 'mainnet-beta';

export const INVALID_BUT_SUFFICIENT_FOR_COMPILATION_BLOCKHASH: {
  blockhash: Blockhash;
  lastValidBlockHeight: bigint;
  slot: bigint;
} = {
  blockhash: '11111111111111111111111111111111' as Blockhash,
  lastValidBlockHeight: 0n,
  slot: 0n,
};

export function base64EncodeTx(
  cluster: 'mainnet-beta' | 'devnet' | 'localnet',
  payer: Address,
  instructions: Instruction[],
  lookupTables: Account<AddressLookupTable>[] | undefined = undefined,
): {
  simulationUrl: string;
} {
  const luts: AddressesByLookupTableAddress = {};
  (lookupTables || []).forEach((lut) => {
    luts[lut.address] = lut.data.addresses;
  });

  const transactionMessage = buildTransactionMessage(
    instructions,
    payer,
    INVALID_BUT_SUFFICIENT_FOR_COMPILATION_BLOCKHASH,
    lookupTables,
  );
  const compiled = compileTransactionMessage(transactionMessage);
  const encodedMessageBytes = getCompiledTransactionMessageEncoder().encode(compiled);
  const encodedTxMessage = Buffer.from(encodedMessageBytes).toString('base64');
  const clusterString =
    cluster === 'localnet' ? '?cluster=custom&customUrl=http://localhost:8899' : `?cluster=${cluster.toString()}`;
  const simulationUrl = `https://explorer.solana.com/tx/inspector${clusterString}&message=${encodeURIComponent(
    encodedTxMessage,
  )}&signatures=${encodeURIComponent(`[${payer}]`)}`;
  return { simulationUrl };
}

export async function sendTx(
  rpc: Rpc<SendTransactionApi & GetTransactionApi>,
  tx: FullySignedTransaction,
  sig: Signature,
  blockhash: { blockhash: string; slot: bigint },
  withDescription: string = '',
  logger: (str: string) => void = console.log,
): Promise<Signature> {
  const serialized = getBase64EncodedWireTransaction(tx);
  const link = `https://solscan.io/tx/${sig}`;
  logger(`${withDescription} ${link}`);
  try {
    await rpc
      .sendTransaction(serialized, {
        encoding: 'base64',
        preflightCommitment: 'confirmed',
        maxRetries: 0n,
        skipPreflight: true,
        minContextSlot: blockhash.slot,
      })
      .send();
    return sig;
  } catch (e) {
    logger(`${withDescription} ${sig}, RPC rejected transaction  with the following error:\n ${e}`);
    const errString: string = e.toString();
    if (errString.includes('failed')) {
      const sig = e.toString().split(' failed ')[0].split('Transaction ')[1];
      if (!sig) {
        throw e;
      }
      const failedTx: TransactionResponse | null = await forceGetConfirmedTx(rpc, sig);
      if (!failedTx) {
        throw new TransactionError(e.message, sig, undefined, e);
      } else {
        let logs: string[] | undefined = undefined;
        if (failedTx.meta?.logMessages) {
          logs = [...failedTx.meta.logMessages];
        }
        throw new TransactionError(e.message, sig, logs, e);
      }
    } else {
      throw e;
    }
  }
}

export function removeComputeBudgetIxns(ixns: Instruction[]): Instruction[] {
  return ixns.filter(({ programAddress }) => programAddress !== COMPUTE_BUDGET_PROGRAM_ADDRESS);
}

export async function sendAndConfirmTx(
  {
    rpc,
    wsRpc,
  }: {
    rpc: Rpc<GetEpochInfoApi & GetSignatureStatusesApi & SendTransactionApi>;
    wsRpc: RpcSubscriptions<SignatureNotificationsApi & SlotNotificationsApi>;
  },
  tx: FullySignedTransaction,
  slot: bigint,
): Promise<void> {
  await sendAndConfirmTransactionFactory({ rpc, rpcSubscriptions: wsRpc })(
    { ...tx, lifetimeConstraint: { lastValidBlockHeight: slot } },
    {
      commitment: 'confirmed',
      preflightCommitment: 'confirmed',
      maxRetries: 0n,
      skipPreflight: true,
      minContextSlot: slot,
    },
  );
}

export async function sendAndConfirmTransactionV0Impl(
  rpc: {
    rpc: Rpc<GetEpochInfoApi & GetSignatureStatusesApi & SendTransactionApi & GetTransactionApi>;
    wsRpc: RpcSubscriptions<SignatureNotificationsApi & SlotNotificationsApi>;
  },
  sig: Signature,
  tx: FullySignedTransaction,
  slot: bigint,
  withDescription: string = '',
  logger: (str: string) => void = console.log,
): Promise<void> {
  try {
    const link = `https://solscan.io/tx/${sig}`;
    logger(`${withDescription} ${link}`);
    await sendAndConfirmTx(rpc, tx, slot);
  } catch (e) {
    const failedTx = await forceGetConfirmedTx(rpc.rpc, sig);
    if (!failedTx) {
      throw new TransactionError(`Failed to send transaction: ${withDescription} ${sig}`, sig, undefined, e);
    } else {
      let logs: string[] | undefined = undefined;
      if (failedTx.meta?.logMessages) {
        logs = [...failedTx.meta.logMessages];
      }
      throw new TransactionError(`Failed to send transaction: ${withDescription} ${sig}`, sig, logs, e);
    }
  }
}

export async function confirmTx(
  connection: Rpc<SolanaRpcApi>,
  txHash: string,
): Promise<ReturnType<GetTransactionApi['getTransaction']>> {
  const sig = signature(txHash);

  return connection
    .getTransaction(sig, {
      commitment: 'confirmed',
      encoding: 'json',
      maxSupportedTransactionVersion: 0,
    })
    .send();
}

export type TransactionResponse = ReturnType<GetTransactionApi['getTransaction']> | null;

export async function forceGetConfirmedTx(
  rpc: Rpc<GetTransactionApi>,
  sig: Signature,
): Promise<TransactionResponse | null> {
  console.log(`forceGetConfirmedTx: ${sig}`);
  const endTime = Date.now() + 5000;
  let lastErr = null;
  let failedTx: TransactionResponse | null = null;

  while (true) {
    try {
      failedTx = await rpc
        .getTransaction(sig, {
          commitment: 'confirmed',
          maxSupportedTransactionVersion: 0,
          encoding: 'json',
        })
        .send();
      if (failedTx) {
        return failedTx;
      }
    } catch (e) {
      lastErr = e;
    }
    if (Date.now() > endTime) {
      if (lastErr) {
        throw lastErr;
      } else {
        return failedTx;
      }
    }
  }
}

export async function getSimulationComputeUnits(
  c: Rpc<SolanaRpcApi>,
  instructions: Array<Instruction>,
  payer: Address,
  lookupTables: Array<Account<AddressLookupTable>> | [],
  withDescription: string = '',
  logger: (str: string) => void = console.log,
): Promise<number | null> {
  // Set high to ensure it doesn't fail
  const testInstructions = overwriteComputeBudget(instructions, 2_000_000);

  const transactionMessage = buildTransactionMessage(
    testInstructions,
    payer,
    INVALID_BUT_SUFFICIENT_FOR_COMPILATION_BLOCKHASH,
    lookupTables,
  );
  const testTransaction = await signTransactionMessageWithSigners(transactionMessage);

  const encodedTransaction = getBase64EncodedWireTransaction(testTransaction);

  try {
    let rpcResponse = await c
      .simulateTransaction(encodedTransaction, {
        encoding: 'base64',
        replaceRecentBlockhash: true,
        sigVerify: false,
      })
      .send();

    if (rpcResponse.value.err) {
      logger(
        `${withDescription} Error response from simulation: ${JSON.stringify(rpcResponse.value.err)}, logs: ${
          rpcResponse.value.logs
        }`,
      );
      return null;
    }
    // getErrorFromRPCResponse(rpcResponse);
    return Number(rpcResponse.value.unitsConsumed) || null;
  } catch (e) {
    logger(`${withDescription} Error simulating transaction: ${e}`);
    return null;
  }
}

export const getLookupTableAccountsFromKeys = async (
  connection: Rpc<SolanaRpcApi>,
  keys: Address[],
): Promise<Account<AddressLookupTable>[]> => {
  return await fetchAllAddressLookupTable(connection, keys);
};

export function maxLockedAccounts(count: number): number {
  return MAX_LOCKED_ACCOUNTS - count;
}

function isAddressLookupTableAccountArray(items: any[]): items is Account<AddressLookupTable>[] {
  return (
    Array.isArray(items) &&
    items.length > 0 &&
    items.every(
      (item) =>
        item &&
        typeof item === 'object' &&
        'address' in item &&
        'data' in item &&
        item.data &&
        'addresses' in item.data,
    )
  );
}

export function uniqueAccounts(
  ixs: Instruction[],
  addressLookupTables: Address[] | Account<AddressLookupTable>[] = [],
): Set<string> {
  let luts: string[];
  if (isAddressLookupTableAccountArray(addressLookupTables)) {
    luts = addressLookupTables.map((lut) => lut.address);
  } else {
    luts = addressLookupTables.map((k) => k);
  }
  const uniqueAccounts = ixs
    .map((ix) => ix.accounts?.map((k) => k.address.toString()) ?? [])
    .flat()
    .concat(...luts);
  return new Set(uniqueAccounts);
}

export const instructionEquals = (ix1: Instruction, ix2: Instruction) =>
  ix1.programAddress === ix2.programAddress &&
  arrayDeepEquals(ix1.accounts, ix2.accounts, (a, b) => a.role === b.role && a.address === b.address) &&
  arrayDeepEquals(
    ix1.data ? Array.from(ix1.data) : undefined,
    ix2.data ? Array.from(ix2.data) : undefined,
    (a, b) => a === b,
  );

export function arrayDeepEquals<T, U>(
  array1: Readonly<T[]> | undefined,
  array2: Readonly<U[]> | undefined,
  eq: (a: T, b: U) => boolean,
): boolean {
  if (array1 === undefined && array2 === undefined) {
    return true;
  }

  if (array1 === undefined || array2 === undefined) {
    return false;
  }

  if (array1.length !== array2.length) {
    return false;
  }
  return array1.reduce((prev, current, index) => {
    const other = array2[index];
    if (other == null) {
      return false;
    }
    return prev && eq(current, other);
  }, true);
}

export class TransactionError extends Error {
  sig: string;
  logs: string[] | undefined;
  err: Web3TxError | undefined;
  constructor(message: string, sig: string, logs?: string[], err?: Web3TxError) {
    super(message);
    this.sig = sig;
    this.logs = logs;
    this.err = err;
  }
}

export function createAddExtraComputeUnitsTransaction(units: number, feePerCULamports?: Decimal): Instruction[] {
  const ixns = [];
  ixns.push(getSetComputeUnitLimitInstruction({ units }));

  if (feePerCULamports) {
    const { microLamports } = getComputeUnitPrice(units, feePerCULamports);
    ixns.push(getSetComputeUnitPriceInstruction({ microLamports }));
  }
  return ixns;
}

export function getComputeUnitPrice(
  units: number,
  feePerCULamports: Decimal,
): {
  microLamports: bigint;
} {
  const multiplier = 1;
  const unitPrice = feePerCULamports
    .mul(10 ** 6)
    .div(units)
    .mul(multiplier);
  const value = unitPrice.floor().toString();
  console.debug(`Fee per CU lamports: ${feePerCULamports}, units: ${units}, compute unit price: ${value}`);
  return { microLamports: BigInt(value) };
}

export function isComputeBudgetComputeUnitLimit(ix: ComputeBudgetInstruction): boolean {
  return ix === ComputeBudgetInstruction.SetComputeUnitLimit;
}

export function isComputeBudgetComputeUnitPrice(ix: ComputeBudgetInstruction): boolean {
  return ix === ComputeBudgetInstruction.SetComputeUnitPrice;
}

function eliminateConsecutive<T>(arr: T[], comparator?: (a: T, b: T) => boolean): T[] {
  if (!arr.length) return [];

  const result: T[] = [arr[0]];

  for (let i = 1; i < arr.length; i += 1) {
    if (comparator) {
      if (!comparator(arr[i], arr[i - 1])) {
        result.push(arr[i]);
      }
    } else if (arr[i] !== arr[i - 1]) {
      result.push(arr[i]);
    }
  }

  return result;
}

export function overwriteComputeBudget(ixs: Instruction[], units: number): Instruction[] {
  const ixns = ixs.filter(
    (ix) =>
      ix.programAddress !== COMPUTE_BUDGET_PROGRAM_ADDRESS ||
      (ix.data && !isComputeBudgetComputeUnitLimit(identifyComputeBudgetInstruction(ix.data))),
  );
  ixns.unshift(getSetComputeUnitLimitInstruction({ units }));
  return ixns;
}

const SOLANA_COMPASS_API_URL = getEnvOrDefault('SOLANA_COMPASS_API_URL', 'https://solanacompass.com/api');

export async function getRecentAverageFees(cluster: Cluster): Promise<Decimal | undefined> {
  try {
    if (cluster === 'mainnet-beta') {
      return new Decimal(await getAverageFeesPerCUForPeriodLamports(1));
    }
    return undefined;
  } catch (e) {
    console.warn('Failed to get average fees', e);
    return undefined;
  }
}

export async function getAverageFeesPerCUForPeriodLamports(periodMins: 1 | 5 | 15): Promise<number> {
  const averageFees = await getAverageFees();
  return averageFees[periodMins].avg;
}

export async function getAverageFees(): Promise<SolanaCompassFeesByPeriod> {
  const res = await fetch(`${SOLANA_COMPASS_API_URL}/fees`);
  return (await res.json()) as SolanaCompassFeesByPeriod;
}

export type SolanaCompassFeesByPeriod = {
  1: SolanaCompassFees;
  5: SolanaCompassFees;
  15: SolanaCompassFees;
};

export type SolanaCompassFees = {
  min: number;
  max: number;
  avg: number;
  priorityTx: number;
  nonVotes: number;
  priorityRatio: number;
  avgCuPerBlock: number;
  blockspaceUsageRatio: number;
};

export type RpcPriorityFees = {
  min: Decimal;
  max: Decimal;
  average: Decimal;
  median: Decimal;
};

/**
 * Supports the [Triton improved recent priority fee api](https://docs.triton.one/chains/solana/improved-priority-fees-api) which adds a percentile parameter to the getRecentPrioritizationFees rpc call.
 * @param c
 * @param rpcEndpoint
 * @param config
 */
export async function getRpcRecentFeesOfPercentile(
  c: Rpc<SolanaRpcApi>,
  rpcEndpoint: string,
  config: GetRecentPrioritizationFeesConfig,
): Promise<RpcPriorityFees> {
  const percentileStr = `${config.percentile ? ` P[${config.percentile / 100}]` : ''}`;
  const accStr = config.addresses?.length || 'all global';
  console.log(`Fetching recent${percentileStr} priority fees from RPC for ${accStr} accounts`);
  const [res, slot] = await Promise.all([
    getRpcRecentPrioritizationFeesWithPercentile(config, rpcEndpoint),
    c.getSlot().send(),
  ]);
  const validSlot = Number(slot) - SLOTS_PER_MINUTE;
  let filteredZeros = 0;
  let filteredOld = 0;
  let total = new Decimal('0');
  const recentFees = res.result
    .filter((f: RecentPrioritizationFees) => {
      if (f.prioritizationFee <= 0) {
        filteredZeros++;
        return false;
      }
      if (f.slot < validSlot) {
        filteredOld++;
        return false;
      }
      total = total.add(f.prioritizationFee);
      return true;
    })
    .sort((a: RecentPrioritizationFees, b: RecentPrioritizationFees) => a.prioritizationFee - b.prioritizationFee);
  if (recentFees.length === 0) {
    console.log(
      `No valid 1 minute${percentileStr} priority fees returned from RPC for ${accStr} accounts, using 1 uLamports/CU. Filtered ${filteredZeros} zero fees and ${filteredOld} >1 minute fees`,
    );
    return {
      min: new Decimal('1'),
      max: new Decimal('1'),
      average: new Decimal('1'),
      median: new Decimal('1'),
    };
  }
  if (recentFees.length === 1) {
    console.log(
      `Fetched 1 valid 1 minute${percentileStr} priority fee from RPC for ${accStr} accounts, fee: ${recentFees[0].prioritizationFee} uLamports/CU. Filtered ${filteredZeros} zero fees and ${filteredOld} >1 minute fees`,
    );
    return {
      min: new Decimal(recentFees[0].prioritizationFee),
      max: new Decimal(recentFees[0].prioritizationFee),
      average: new Decimal(recentFees[0].prioritizationFee),
      median: new Decimal(recentFees[0].prioritizationFee),
    };
  }
  const min = new Decimal(recentFees[0].prioritizationFee);
  const max = new Decimal(recentFees[recentFees.length - 1].prioritizationFee);
  const average = total.div(recentFees.length);
  const median = new Decimal(recentFees[Math.floor(recentFees.length / 2)].prioritizationFee);
  console.log(
    `Fetched ${recentFees.length} valid 1 minute${percentileStr} priority fees from RPC for ${accStr} accounts, median: ${median} uLamports/CU, average: ${average} uLamports/CU, min: ${min} uLamports/CU, max: ${max} uLamports/CU. Filtered ${filteredZeros} zero fees and ${filteredOld} >1 minute fees`,
  );
  return {
    min,
    max,
    average,
    median,
  };
}

/**
 * Supports the [Triton improved recent priority fee api](https://docs.triton.one/chains/solana/improved-priority-fees-api) which adds a percentile parameter to the getRecentPrioritizationFees rpc call.
 * @param rpcEndpoint
 * @param config
 */
async function getRpcRecentPrioritizationFeesWithPercentile(
  config: GetRecentPrioritizationFeesConfig,
  rpcEndpoint: string,
): Promise<RpcResult> {
  const accounts = config?.addresses || [];
  const percentileConfig = config.percentile ? { percentile: config.percentile } : {};

  const response = await fetch(rpcEndpoint, {
    method: 'POST',
    headers: {
      Accept: 'application/json',
      'Content-Type': 'application/json',
      'Cache-Control': 'no-cache',
    },
    body: JSON.stringify({
      method: 'getRecentPrioritizationFees',
      jsonrpc: '2.0',
      params: [
        [...accounts],
        {
          ...percentileConfig,
        },
      ],
      id: uuidv4(),
    }),
  });

  if (!response.ok) {
    throw new Error(`Network response was not ok: ${response.statusText}`);
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const unsafeRes: any = await response.json();

  if ('error' in unsafeRes) {
    throw new SolanaJSONRPCError(
      unsafeRes.error,
      `Failed to get recent priority fees by accounts: ${config?.addresses || []}`,
    );
  }

  return unsafeRes as RpcResult;
}

type GetRecentPrioritizationFeesConfig = {
  addresses?: Address[];
  /**
   * bps percentile to use for prioritization fee calculation
   */
  percentile?: number;
};

interface RpcResult {
  jsonrpc: string;
  result: Array<RecentPrioritizationFees>;
}
